    if t>max(e) and t-max(e)<=20: (fw if d>0 else bw).append(y)
    if t<min(e) and min(e)-t<=20: (fw if d<0 else bw).append(y)
  # ratio-based: log distance
m=lambda a:(sum(a)/len(a),len(a))
print('up',m(up),'dn',m(dn),'fw',m(fw),'bw',m(bw))
# compare log-distance vs linear: bucket by distance, up vs down
for lo,hi in [(1,5),(6,10),(11,20),(21,40)]:
  u=[];d=[]
  for x in r:
    e=[int(v) for v in x['number_set'].split(',')];t=int(x['target']);y=int(x['rating'])
    if lo<=t-max(e)<=hi: u.append(y)
    if lo<=min(e)-t<=hi: d.append(y)
  print(lo,hi,m(u) if u else None,m(d) if d else None)
"

